# ShedNaja: ctypes.util.find_library() cannot find anything on this uClibc rootfs
# (it relies on ldconfig, gcc or objdump, none of which are installed), and the usual
# fallback names like "libc.so.6" are glibc-only. Moonraker's dependencies load
# libraries that way (inotify_simple: libc, libnacl: libsodium), so look in the
# library directories directly first.
import ctypes.util as _cu
import glob as _glob

_orig_find_library = _cu.find_library


def _find_library(name):
    for d in ("/lib", "/usr/lib"):
        hits = sorted(_glob.glob("%s/lib%s.so*" % (d, name)))
        if hits:
            return hits[0]
    return _orig_find_library(name)


_cu.find_library = _find_library


# uClibc has no getloadavg(), so Python is built without os.getloadavg. Klipper's
# statistics module calls it every few seconds and shuts the printer down with an
# AttributeError (seen on the first step-2 boot). Read /proc/loadavg instead.
import os as _os

if not hasattr(_os, "getloadavg"):
    def _getloadavg():
        with open("/proc/loadavg") as f:
            return tuple(float(x) for x in f.read().split()[:3])

    _os.getloadavg = _getloadavg
